    """Normalize only an explicit, single dollar amount."""
    matches = re.findall(r"(?:CAD\s*)?\$\s*([\d,]+(?:\.\d{1,2})?)", text, re.I)
    if len(matches) != 1:
        return None
    try:
        return Decimal(matches[0].replace(",", ""))
    except InvalidOperation:
        return None
