def normalize_percentage(text: str) -> Decimal | None:
    matches = re.findall(r"(?<!\d)(\d{1,3}(?:\.\d+)?)\s*%", text)
    if len(matches) != 1:
        return None
    value = Decimal(matches[0])
    return value if value <= 100 else None

